using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Nakama.Api.Modules.Identity.Domain;
using Nakama.Api.Modules.Projects.Domain;
using Nakama.Api.Modules.Tasks.Domain;
namespace Nakama.Api.Modules.Tasks.Infrastructure;
public sealed class WorkTaskConfiguration:IEntityTypeConfiguration<WorkTask>{public void Configure(EntityTypeBuilder<WorkTask>b){b.ToTable("tasks",t=>{t.HasCheckConstraint("ck_tasks_status","status IN ('Pending', 'InProgress', 'InReview', 'Blocked', 'Completed', 'Cancelled')");t.HasCheckConstraint("ck_tasks_priority","priority IN ('Low', 'Medium', 'High', 'Critical')");t.HasCheckConstraint("ck_tasks_status_before_blocked","status_before_blocked IS NULL OR status_before_blocked IN ('Pending', 'InProgress', 'InReview')");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.ProjectId).HasColumnName("project_id");b.Property(x=>x.StageId).HasColumnName("stage_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(300);b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(4000);b.Property(x=>x.Status).HasColumnName("status").HasMaxLength(32).HasConversion<string>();b.Property(x=>x.StatusBeforeBlocked).HasColumnName("status_before_blocked").HasMaxLength(32).HasConversion<string>();b.Property(x=>x.Priority).HasColumnName("priority").HasMaxLength(32).HasConversion<string>();b.Property(x=>x.DueDate).HasColumnName("due_date").HasColumnType("timestamp with time zone");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasColumnType("timestamp with time zone");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").HasColumnType("timestamp with time zone");b.Property(x=>x.CompletedAt).HasColumnName("completed_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.ProjectId);b.HasIndex(x=>x.StageId);b.HasIndex(x=>x.Status);b.HasIndex(x=>x.Priority);b.HasIndex(x=>x.DueDate);b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Stage>().WithMany().HasForeignKey(x=>x.StageId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TaskAssigneeConfiguration:IEntityTypeConfiguration<TaskAssignee>{public void Configure(EntityTypeBuilder<TaskAssignee>b){b.ToTable("task_assignees");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.UserId).HasColumnName("user_id");b.Property(x=>x.AssignedAt).HasColumnName("assigned_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.TaskId);b.HasIndex(x=>x.UserId);b.HasIndex(x=>new{x.TaskId,x.UserId}).IsUnique();b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TaskBlockerConfiguration:IEntityTypeConfiguration<TaskBlocker>{public void Configure(EntityTypeBuilder<TaskBlocker>b){b.ToTable("task_blockers",t=>t.HasCheckConstraint("ck_task_blockers_type","type IN ('Dependency', 'Information', 'Approval', 'TechnicalIssue', 'External', 'Other')"));b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.Type).HasColumnName("type").HasMaxLength(32).HasConversion<string>();b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(1000);b.Property(x=>x.ReportedByUserId).HasColumnName("reported_by_user_id");b.Property(x=>x.ReportedAt).HasColumnName("reported_at").HasColumnType("timestamp with time zone");b.Property(x=>x.ResolvedByUserId).HasColumnName("resolved_by_user_id");b.Property(x=>x.ResolvedAt).HasColumnName("resolved_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.TaskId).HasDatabaseName("ix_task_blockers_task_id");b.HasIndex(x=>x.ReportedByUserId);b.HasIndex(x=>x.ResolvedAt);b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ReportedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ResolvedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class SubtaskConfiguration:IEntityTypeConfiguration<Subtask>{public void Configure(EntityTypeBuilder<Subtask>b){b.ToTable("subtasks",t=>t.HasCheckConstraint("ck_subtasks_position","position >= 1"));b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(300);b.Property(x=>x.Position).HasColumnName("position");b.Property(x=>x.IsCompleted).HasColumnName("is_completed");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CompletedByUserId).HasColumnName("completed_by_user_id");b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasColumnType("timestamp with time zone");b.Property(x=>x.CompletedAt).HasColumnName("completed_at").HasColumnType("timestamp with time zone");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.TaskId);b.HasIndex(x=>x.CreatedByUserId);b.HasIndex(x=>new{x.TaskId,x.Position}).IsUnique();b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.CompletedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TaskDependencyConfiguration:IEntityTypeConfiguration<TaskDependency>{public void Configure(EntityTypeBuilder<TaskDependency>b){b.ToTable("task_dependencies",t=>t.HasCheckConstraint("ck_task_dependencies_no_self","task_id <> depends_on_task_id"));b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.DependsOnTaskId).HasColumnName("depends_on_task_id");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.TaskId);b.HasIndex(x=>x.DependsOnTaskId);b.HasIndex(x=>new{x.TaskId,x.DependsOnTaskId}).IsUnique();b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.DependsOnTaskId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TaskCommentConfiguration:IEntityTypeConfiguration<TaskComment>{public void Configure(EntityTypeBuilder<TaskComment>b){b.ToTable("task_comments");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.AuthorUserId).HasColumnName("author_user_id");b.Property(x=>x.Content).HasColumnName("content").HasMaxLength(4000);b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasColumnType("timestamp with time zone");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>new{x.TaskId,x.CreatedAt});b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.AuthorUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TaskAttachmentConfiguration:IEntityTypeConfiguration<TaskAttachment>{public void Configure(EntityTypeBuilder<TaskAttachment>b){b.ToTable("task_attachments");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.TaskId).HasColumnName("task_id");b.Property(x=>x.UploadedByUserId).HasColumnName("uploaded_by_user_id");b.Property(x=>x.OriginalFileName).HasColumnName("original_file_name").HasMaxLength(260);b.Property(x=>x.StoredFileName).HasColumnName("stored_file_name").HasMaxLength(128);b.Property(x=>x.ContentType).HasColumnName("content_type").HasMaxLength(128);b.Property(x=>x.SizeBytes).HasColumnName("size_bytes");b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasColumnType("timestamp with time zone");b.HasIndex(x=>x.TaskId);b.HasIndex(x=>x.UploadedByUserId);b.HasOne<WorkTask>().WithMany().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.UploadedByUserId).OnDelete(DeleteBehavior.Restrict);}}
